PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE site_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE stories (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  genre TEXT NOT NULL DEFAULT 'Unknown',
  status TEXT NOT NULL DEFAULT 'Unknown',
  cover TEXT NOT NULL DEFAULT '',
  visible INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 9999,
  source_url TEXT NOT NULL DEFAULT '',
  drive_url TEXT NOT NULL DEFAULT '',
  checked TEXT NOT NULL DEFAULT 'Never',
  automatic_check INTEGER NOT NULL DEFAULT 1,
  manual_lock INTEGER NOT NULL DEFAULT 0,
  confidence INTEGER NOT NULL DEFAULT 0,
  status_last_checked TEXT,
  genre_last_checked TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, drive_root_id TEXT NOT NULL DEFAULT '', drive_root_url TEXT NOT NULL DEFAULT '', drive_root_name TEXT NOT NULL DEFAULT '', drive_root_owner_email TEXT NOT NULL DEFAULT '', drive_path TEXT NOT NULL DEFAULT '');
CREATE TABLE membership_tiers (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  price TEXT NOT NULL DEFAULT '$0.00',
  cycle TEXT NOT NULL DEFAULT '/ month',
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'Draft',
  benefits_json TEXT NOT NULL DEFAULT '[]',
  cover TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 9999,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_sessions (
  token_hash TEXT PRIMARY KEY,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL
);
CREATE TABLE activity_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL DEFAULT 'system',
  title TEXT NOT NULL,
  detail TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL COLLATE NOCASE UNIQUE,
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  password_iterations INTEGER NOT NULL DEFAULT 120000,
  account_status TEXT NOT NULL DEFAULT 'Active',
  membership_status TEXT NOT NULL DEFAULT 'None',
  membership_tier_id TEXT,
  membership_plan TEXT NOT NULL DEFAULT 'None',
  membership_started_at TEXT,
  membership_expires_at TEXT,
  payment_status TEXT NOT NULL DEFAULT 'None',
  latest_amount TEXT NOT NULL DEFAULT '$0.00',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_login_at TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (membership_tier_id) REFERENCES membership_tiers(id) ON DELETE SET NULL
);
CREATE TABLE user_sessions (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE story_covers (
  story_id TEXT PRIMARY KEY,
  mime_type TEXT NOT NULL,
  image_data BLOB NOT NULL,
  size_bytes INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);
CREATE TABLE media_assets (
  asset_key TEXT PRIMARY KEY,
  mime_type TEXT NOT NULL,
  image_data BLOB NOT NULL,
  size_bytes INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);
CREATE TABLE chat_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  sender_role TEXT NOT NULL CHECK (sender_role IN ('member','admin')),
  body TEXT NOT NULL,
  created_at TEXT NOT NULL,
  delivered_at TEXT,
  seen_at TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE payment_provider_settings (
  provider TEXT PRIMARY KEY,
  enabled INTEGER NOT NULL DEFAULT 0,
  mode TEXT NOT NULL DEFAULT 'sandbox',
  client_id TEXT NOT NULL DEFAULT '',
  webhook_id TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, support_enabled INTEGER NOT NULL DEFAULT 0, support_email TEXT NOT NULL DEFAULT '', support_min_amount INTEGER NOT NULL DEFAULT 9);
CREATE TABLE membership_payment_plans (
  tier_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  external_plan_id TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (tier_id, provider),
  FOREIGN KEY (tier_id) REFERENCES membership_tiers(id) ON DELETE CASCADE
);
CREATE TABLE payment_checkout_sessions (
  token TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  tier_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  external_plan_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used_at TEXT, environment TEXT NOT NULL DEFAULT '',
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (tier_id) REFERENCES membership_tiers(id) ON DELETE CASCADE
);
CREATE TABLE member_subscriptions (
  provider_subscription_id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  user_id TEXT NOT NULL,
  tier_id TEXT,
  external_plan_id TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'APPROVAL_PENDING',
  next_billing_at TEXT,
  last_payment_at TEXT,
  started_at TEXT,
  cancelled_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, environment TEXT NOT NULL DEFAULT '',
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (tier_id) REFERENCES membership_tiers(id) ON DELETE SET NULL
);
CREATE TABLE payment_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  provider TEXT NOT NULL,
  provider_event_id TEXT NOT NULL UNIQUE,
  event_type TEXT NOT NULL,
  user_id TEXT,
  provider_subscription_id TEXT,
  amount TEXT NOT NULL DEFAULT '',
  currency TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'Processed',
  occurred_at TEXT,
  created_at TEXT NOT NULL, environment TEXT NOT NULL DEFAULT '', user_name_snapshot TEXT NOT NULL DEFAULT '', user_email_snapshot TEXT NOT NULL DEFAULT '',
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE finance_record_overrides (
  record_key TEXT PRIMARY KEY,
  environment TEXT NOT NULL DEFAULT '',
  exclude_from_revenue INTEGER NOT NULL DEFAULT 0,
  hidden INTEGER NOT NULL DEFAULT 0,
  note TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE support_checkout_sessions (
  token TEXT PRIMARY KEY,
  provider_order_id TEXT NOT NULL UNIQUE,
  user_id TEXT NOT NULL,
  amount TEXT NOT NULL,
  currency TEXT NOT NULL DEFAULT 'USD',
  environment TEXT NOT NULL DEFAULT 'sandbox',
  status TEXT NOT NULL DEFAULT 'CREATED',
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  completed_at TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE admin_notifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL DEFAULT 'system',
  title TEXT NOT NULL,
  body TEXT NOT NULL DEFAULT '',
  target_route TEXT NOT NULL DEFAULT '',
  user_id TEXT,
  related_key TEXT NOT NULL DEFAULT '',
  read_at TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE user_client_context (
  user_id TEXT PRIMARY KEY,
  timezone TEXT NOT NULL DEFAULT '',
  locale TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE user_google_auth (
  user_id TEXT PRIMARY KEY,
  google_sub TEXT NOT NULL UNIQUE,
  google_email TEXT NOT NULL COLLATE NOCASE,
  picture_url TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE admin_login_rate_limits (
  client_key TEXT PRIMARY KEY,
  failure_count INTEGER NOT NULL DEFAULT 0,
  window_started_at TEXT NOT NULL,
  locked_until TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE lifetime_story_products (
  id TEXT PRIMARY KEY,
  current_story_id TEXT UNIQUE,
  state TEXT NOT NULL DEFAULT 'Active',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (current_story_id) REFERENCES stories(id) ON DELETE SET NULL
);
CREATE TABLE story_identity_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  permanent_story_id TEXT NOT NULL,
  story_id_snapshot TEXT NOT NULL DEFAULT '',
  title TEXT NOT NULL DEFAULT '',
  title_key TEXT NOT NULL DEFAULT '',
  drive_url TEXT NOT NULL DEFAULT '',
  drive_folder_id TEXT NOT NULL DEFAULT '',
  cover TEXT NOT NULL DEFAULT '',
  recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (permanent_story_id) REFERENCES lifetime_story_products(id) ON DELETE CASCADE
);
CREATE TABLE story_lifetime_purchases (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  user_name_snapshot TEXT NOT NULL DEFAULT '',
  user_email_snapshot TEXT NOT NULL DEFAULT '',
  permanent_story_id TEXT NOT NULL,
  original_story_id TEXT NOT NULL DEFAULT '',
  original_title TEXT NOT NULL DEFAULT '',
  original_drive_url TEXT NOT NULL DEFAULT '',
  original_drive_folder_id TEXT NOT NULL DEFAULT '',
  original_cover TEXT NOT NULL DEFAULT '',
  amount TEXT NOT NULL DEFAULT '49.00',
  currency TEXT NOT NULL DEFAULT 'USD',
  provider TEXT NOT NULL DEFAULT 'paypal',
  environment TEXT NOT NULL DEFAULT '',
  paypal_order_id TEXT,
  paypal_capture_id TEXT,
  purchase_status TEXT NOT NULL DEFAULT 'Completed',
  entitlement_status TEXT NOT NULL DEFAULT 'Active',
  purchased_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (permanent_story_id) REFERENCES lifetime_story_products(id) ON DELETE RESTRICT,
  UNIQUE (user_id, permanent_story_id),
  UNIQUE (paypal_order_id),
  UNIQUE (paypal_capture_id)
);
CREATE TABLE lifetime_story_assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  permanent_story_id TEXT NOT NULL,
  from_story_id TEXT NOT NULL DEFAULT '',
  to_story_id TEXT NOT NULL DEFAULT '',
  source TEXT NOT NULL DEFAULT 'system',
  reason TEXT NOT NULL DEFAULT '',
  note TEXT NOT NULL DEFAULT '',
  changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (permanent_story_id) REFERENCES lifetime_story_products(id) ON DELETE CASCADE
);
CREATE TABLE lifetime_story_checkout_sessions (
  token TEXT PRIMARY KEY,
  paypal_order_id TEXT UNIQUE,
  paypal_approve_url TEXT NOT NULL DEFAULT '',
  user_id TEXT NOT NULL,
  permanent_story_id TEXT NOT NULL,
  story_id_snapshot TEXT NOT NULL DEFAULT '',
  title_snapshot TEXT NOT NULL DEFAULT '',
  drive_url_snapshot TEXT NOT NULL DEFAULT '',
  drive_folder_id_snapshot TEXT NOT NULL DEFAULT '',
  cover_snapshot TEXT NOT NULL DEFAULT '',
  amount TEXT NOT NULL DEFAULT '49.00',
  currency TEXT NOT NULL DEFAULT 'USD',
  environment TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'INIT',
  paypal_capture_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL,
  completed_at TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (permanent_story_id) REFERENCES lifetime_story_products(id) ON DELETE CASCADE,
  UNIQUE (paypal_capture_id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_stories_public ON stories (visible, sort_order, title);
CREATE INDEX idx_stories_status ON stories (status);
CREATE INDEX idx_membership_tiers_public ON membership_tiers (status, sort_order, name);
CREATE INDEX idx_admin_sessions_expires ON admin_sessions (expires_at);
CREATE INDEX idx_users_email ON users (email);
CREATE INDEX idx_users_membership ON users (account_status, membership_status, membership_expires_at);
CREATE INDEX idx_users_created ON users (created_at DESC);
CREATE INDEX idx_user_sessions_user ON user_sessions (user_id);
CREATE INDEX idx_user_sessions_expires ON user_sessions (expires_at);
CREATE INDEX idx_media_assets_updated ON media_assets(updated_at);
CREATE INDEX idx_chat_messages_user_id ON chat_messages (user_id, id);
CREATE INDEX idx_chat_messages_delivery ON chat_messages (sender_role, delivered_at, id);
CREATE INDEX idx_chat_messages_seen ON chat_messages (sender_role, seen_at, id);
CREATE INDEX idx_payment_checkout_user ON payment_checkout_sessions(user_id, expires_at);
CREATE INDEX idx_member_subscriptions_user ON member_subscriptions(user_id, status);
CREATE INDEX idx_payment_events_created ON payment_events(created_at DESC);
CREATE INDEX idx_support_checkout_user ON support_checkout_sessions(user_id, created_at DESC);
CREATE INDEX idx_admin_notifications_unread ON admin_notifications(read_at, created_at DESC);
CREATE INDEX idx_admin_notifications_created ON admin_notifications(created_at DESC);
CREATE INDEX idx_user_google_auth_email ON user_google_auth (google_email);
CREATE INDEX idx_admin_login_rate_limits_updated
  ON admin_login_rate_limits(updated_at);
CREATE INDEX idx_lifetime_story_products_state
  ON lifetime_story_products(state, updated_at DESC);
CREATE INDEX idx_story_identity_history_story
  ON story_identity_history(story_id_snapshot, id DESC);
CREATE INDEX idx_story_identity_history_drive_folder
  ON story_identity_history(drive_folder_id, id DESC);
CREATE INDEX idx_story_identity_history_title_key
  ON story_identity_history(title_key, id DESC);
CREATE INDEX idx_story_identity_history_product
  ON story_identity_history(permanent_story_id, id DESC);
CREATE INDEX idx_story_lifetime_purchases_user
  ON story_lifetime_purchases(user_id, purchased_at DESC);
CREATE INDEX idx_story_lifetime_purchases_product
  ON story_lifetime_purchases(permanent_story_id, purchased_at DESC);
CREATE INDEX idx_story_lifetime_purchases_status
  ON story_lifetime_purchases(entitlement_status, purchase_status, purchased_at DESC);
CREATE INDEX idx_lifetime_story_assignments_product
  ON lifetime_story_assignments(permanent_story_id, id DESC);
CREATE INDEX idx_lifetime_checkout_user_story
  ON lifetime_story_checkout_sessions(user_id, permanent_story_id, created_at DESC);
CREATE INDEX idx_lifetime_checkout_expires
  ON lifetime_story_checkout_sessions(status, expires_at);
